#!/bin/bash
# round-2 keyframes: start/end frames to lock motion direction (CLI nano_banana_flash ~2cr)
cd "$(dirname "$0")/.."
NT="No text, no letters anywhere except the number 30 if a speed sign is visible."
gen(){ id=$1; ar=$2; refs=""; for r in $3; do refs="$refs --image-references $r"; done
  ( url=$(higgsfield generate create nano_banana_flash --prompt "$4 $NT" $refs --aspect_ratio $ar --resolution 2k --wait 2>&1 | grep -o 'https://[^ ]*\.png' | tail -1)
    [ -n "$url" ] && curl -s -o "kf2/$id.png" "$url" && echo "$id ok" || echo "$id FAIL" ) & }
SIG="a correct Korean pedestrian traffic signal head: two square lamps stacked vertically on a grey pole; the TOP lamp shows a red standing person and is switched OFF (dark, unlit); the BOTTOM lamp shows a green walking person and is switched ON (bright green glow)"
gen A10s 16:9 "keyframes_ad/A10.png" "Edit this image. Keep everything identical (camera, framing, grandmother, boy, turtle-car behind the stop line, crosswalk, lighting, clay style) but replace the pedestrian traffic light with $SIG."
gen A15s 16:9 "keyframes_ad/A15.png chars/rabbit.png" "Edit the first image. Keep the same camera, street, red road and the speed enforcement camera pole exactly the same, but: there is NO flash at all, and the red rabbit-car is much further back up the road, small in the distance, driving toward the camera with its long rabbit ears standing straight up and a smug, cocky face."
gen A15e 16:9 "keyframes_ad/A15.png chars/rabbit.png" "Edit the first image. Keep the same camera, street, red road and the speed enforcement camera pole exactly the same, but: there is NO flash, and the red rabbit-car is closer to the camera than in the image, braking hard with small skid marks, its long rabbit ears drooping down limply along its sides, eyes wide and mouth open in shock."
gen A16 16:9 "keyframes_ad/A15.png chars/hodungi.png chars/rabbit.png" "Claymation stop-motion film still, Aardman-like plasticine. Same street and red road as the first image with the speed enforcement camera pole visible in the background. The red rabbit-car (third reference) is stopped at the roadside with its long rabbit ears drooping down limply, looking embarrassed. In front of it stands the mascot (second reference: green helmet with black traffic-light visor showing red, yellow and green lights, white side horn, green suit, seatbelt with red-button buckle, bare peach hands), wagging its index finger in a playful no-no gesture. Cinematic 16:9 medium shot, warm light."
gen A03e 16:9 "keyframes_ad/A03.png" "Edit this image. Same camera, same street and buildings, same lighting and clay style. The plain green car (no shell) has moved a little forward and is still calm in the left foreground; the red rabbit-car has overtaken it and is now far ahead in the distance, small, driving away from the camera (rear view) with a clay dust trail behind it."
gen A07e 16:9 "keyframes_ad/A07.png" "Edit this image. Same camera, same school-zone street, sidewalk and lighting. The red rabbit-car has sped away and is now far down the red road, small, seen from behind, with a clay dust trail; the grandmother on the sidewalk is still startled, turned to look after it, clutching her bag."
gen A14n 16:9 "keyframes_fix/A14.png" "Edit this image. Keep everything identical (camera, the young woman with yellow helmet on the electric kick scooter, bicycle lane, cars, houses, cherry tree, lighting, clay style) but remove every hanging banner, flag and signboard that has any letters or symbols; replace them with plain blank clay banners or nothing. Make sure she rides inside the marked bicycle lane."
gen S10s 9:16 "keyframes_fix/S10.png chars/rabbit.png" "Edit the first image. Keep the same camera, red road and the speed enforcement camera pole exactly the same, but: there is NO flash, and the red rabbit-car is further back up the road, smaller, driving toward the camera with its long rabbit ears standing straight up and a smug, cocky face."
gen S10e 9:16 "keyframes_fix/S10.png chars/rabbit.png" "Edit the first image. Keep the same camera, red road and the speed enforcement camera pole exactly the same, but: there is NO flash, and the red rabbit-car is closer to the camera, braking hard with small skid marks, its long rabbit ears drooping down limply, eyes wide and mouth open in shock."
wait
